:root {
  --bg: #ffffff;
  --bg-soft: #f7f7ff;
  --card: #ffffff;
  --text: #141428;
  --muted: #5e6077;
  --primary: #6d45ff;
  --primary-2: #8a5bff;
  --primary-dark: #4e2de1;
  --border: #e8e8f2;
  --success: #0f9b6f;
  --shadow: 0 10px 30px rgba(48, 26, 128, 0.08);
  --radius: 16px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; font-family: Inter, "Plus Jakarta Sans", system-ui, -apple-system, Segoe UI, Roboto, sans-serif; color: var(--text); background: var(--bg); }
a { color: inherit; text-decoration: none; }
.container { width: min(1160px, 92vw); margin: 0 auto; }
.section { padding: 72px 0; }
.section.alt { background: var(--bg-soft); }
.badge { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; color: var(--primary-dark); background: #ede8ff; padding: 8px 12px; border-radius: 999px; }
.nav-wrap { position: sticky; top: 0; z-index: 40; background: rgba(255,255,255,.9); backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); }
.nav { display: flex; align-items: center; justify-content: space-between; height: 74px; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 22px; }
.logo-dot { width: 30px; height: 30px; border-radius: 10px; background: linear-gradient(145deg, var(--primary), #b36cff); box-shadow: var(--shadow); }
.nav-links { display: flex; gap: 26px; align-items: center; }
.nav-links a { color: var(--muted); font-weight: 600; }
.nav-actions { display: flex; gap: 12px; align-items: center; }
.btn { display:inline-flex; align-items:center; justify-content:center; border:1px solid transparent; border-radius:12px; padding:12px 18px; font-weight:700; transition:.2s ease; cursor:pointer; }
.btn-primary { background: linear-gradient(135deg, var(--primary), var(--primary-2)); color:#fff; box-shadow: 0 8px 22px rgba(109,69,255,.35); }
.btn-primary:hover { transform: translateY(-1px); filter: brightness(1.03); }
.btn-secondary { background:#fff; border-color:var(--border); color:var(--text); }
.btn-secondary:hover { border-color: #d2d2e6; }
h1 { font-size: clamp(34px, 5vw, 58px); line-height: 1.05; margin: 18px 0; }
h2 { font-size: clamp(28px, 3.5vw, 42px); margin: 0 0 14px; }
h3 { margin: 0 0 8px; font-size: 20px; }
p.lead { color: var(--muted); font-size: 18px; line-height: 1.6; max-width: 64ch; }
.grid { display:grid; gap:22px; }
.grid-2 { grid-template-columns: repeat(2, minmax(0,1fr)); }
.grid-3 { grid-template-columns: repeat(3, minmax(0,1fr)); }
.grid-4 { grid-template-columns: repeat(4, minmax(0,1fr)); }
.card { background:var(--card); border:1px solid var(--border); border-radius: var(--radius); padding:24px; box-shadow: var(--shadow); }
.hero { padding: 72px 0 56px; background: radial-gradient(circle at top right, rgba(138,91,255,.16), transparent 35%), radial-gradient(circle at 20% 20%, rgba(109,69,255,.1), transparent 28%); }
.hero-layout { display:grid; grid-template-columns: 1.1fr .9fr; gap: 28px; align-items:center; }
.mockup { border-radius: 24px; border: 1px solid var(--border); background: linear-gradient(180deg, #fff, #f8f5ff); padding: 20px; box-shadow: var(--shadow); }
.mockup-screen { height: 300px; border-radius: 16px; background: linear-gradient(135deg, #201452, #7040ff); position: relative; overflow: hidden; }
.mockup-chip { position:absolute; background: rgba(255,255,255,.9); color:#2a2165; border-radius: 999px; padding: 8px 12px; font-size: 12px; font-weight: 700; }
.list-clean { list-style:none; margin:0; padding:0; display:grid; gap:12px; }
.list-clean li { color: var(--muted); }
.small { font-size: 14px; color: var(--muted); }
.footer { padding: 28px 0 40px; border-top: 1px solid var(--border); color: var(--muted); }
.table-wrap { overflow:auto; border:1px solid var(--border); border-radius: 14px; background:#fff; }
table { width:100%; border-collapse: collapse; min-width: 920px; }
th, td { border-bottom:1px solid var(--border); padding:14px 12px; text-align:left; font-size:14px; }
th { background:#f8f8ff; font-size:13px; text-transform:uppercase; letter-spacing:.04em; color:#5a5d76; }
.toggle { display:inline-flex; background:#efeffa; border-radius: 999px; padding:4px; gap:4px; }
.toggle button { border:0; background:transparent; padding:10px 16px; border-radius:999px; font-weight:700; cursor:pointer; color:#55587a; }
.toggle button.active { background:#fff; color:var(--text); box-shadow: 0 2px 10px rgba(0,0,0,.06); }
.save-badge { background:#e7fff3; color:#0a865f; padding:6px 10px; border-radius:999px; font-size:12px; font-weight:700; }
.price { font-size: 40px; font-weight: 800; }
.accordion-item { border:1px solid var(--border); border-radius: 12px; margin-bottom: 10px; overflow:hidden; background:#fff; }
.accordion-btn { width:100%; text-align:left; background:#fff; border:0; padding:16px; font-weight:700; cursor:pointer; }
.accordion-content { max-height:0; overflow:hidden; transition:max-height .25s ease; color:var(--muted); padding:0 16px; }
.accordion-item.open .accordion-content { max-height: 240px; padding-bottom:16px; }
.slider-row { display:flex; align-items:center; gap:14px; }
input[type="range"] { width:100%; accent-color: var(--primary); }
.cookie-banner { position: fixed; left: 18px; right:18px; bottom: 18px; z-index: 70; background:#fff; border:1px solid var(--border); border-radius:16px; box-shadow: var(--shadow); padding:16px; display:flex; gap:14px; align-items:center; justify-content:space-between; }
.cookie-actions { display:flex; gap:10px; flex-wrap:wrap; }
.modal-backdrop { position:fixed; inset:0; background:rgba(18,15,40,.45); display:none; align-items:center; justify-content:center; z-index:90; }
.modal-backdrop.open { display:flex; }
.modal { width:min(560px, 92vw); background:#fff; border-radius:18px; border:1px solid var(--border); padding:22px; }
.switch { display:flex; justify-content:space-between; align-items:center; padding:12px 0; border-bottom:1px solid var(--border); }
.switch input { width:42px; height:22px; }
.auth-layout { min-height: calc(100vh - 74px); display:grid; grid-template-columns: 1fr 1fr; }
.auth-panel { display:flex; align-items:center; justify-content:center; padding:48px 0; }
.auth-card { width:min(430px, 90%); }
.socials { display:grid; gap:10px; margin:18px 0; }
.input { width:100%; border:1px solid var(--border); border-radius:12px; padding:12px 14px; font-size:16px; }
@media (max-width: 980px) {
  .hero-layout, .grid-4, .grid-3, .grid-2, .auth-layout { grid-template-columns: 1fr; }
  .nav-links { display:none; }
}
EOF

